"""Local free-end charts with physical common fibres throughout the interior.

The existing physical body cutter supplies two planes strictly inside every
first/last certified boundary segment. Keep those cuts and every interior
source knot, then prepend/append the exact original endpoints. Only the two
short terminal intervals use independent boundary parameters. In the interior,
the lookup coordinate is the actual projection on the shared Bundle axis.

Admission normally requires separated members over both terminal intervals.
The inner boundaries are affine there; checking their extrapolated gap at the
two axial extremes proves the bound throughout, including unmatched endpoints.
An optional identity proof also admits an end whose four endpoints already
share the physical terminal plane. Its coordinate map needs no adjustment, so
overlap there is still handled by the ordinary physical common-fibre profile.
"""
from . import bundle_axis_nodes as axis


def end_identity(g, raw, origin, direction, length):
    """Prove independently that each end needs no parameter adjustment."""
    physical = g.named('st_axis_xy', 'FLOAT_VECTOR')
    identities = []
    for at_end in (False, True):
        checks = []
        for boundary in raw:
            index = g.math('SUBTRACT', axis._size(g, boundary), 1.) if at_end else 0
            point = g.sample(boundary, physical, index, 'FLOAT_VECTOR')
            metric = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', point, origin), direction)
            checks.append(g.close(metric, length if at_end else 0., axis.AXIS_TOLERANCE))
        identities.append(g.all(*checks))
    return identities


def construct(g, raw, clipped, origin, direction, lateral, length, minimum_gap,
              cut_valid, *, identity_ends=None):
    physical = g.named('st_axis_xy', 'FLOAT_VECTOR')
    rank = g.named('st_station_t', 'FLOAT')
    index = g.node('GeometryNodeInputIndex', 'Local terminal boundary identity').outputs[0]
    checks = [cut_valid]
    count = axis._size(g, raw[0])
    ends = []
    for side, at_end in enumerate((False, True)):
        endpoint = g.math('SUBTRACT', count, 1.) if at_end else 0
        adjacent = g.math('SUBTRACT', count, 2.) if at_end else 1
        first = [g.sample(b, physical, endpoint, 'FLOAT_VECTOR') for b in raw]
        following = [g.sample(b, physical, adjacent, 'FLOAT_VECTOR') for b in raw]
        cut_point = g.sample(clipped[0], physical, endpoint, 'FLOAT_VECTOR')
        cut = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', cut_point, origin), direction)
        metrics = [g.vector('DOT_PRODUCT', g.vector('SUBTRACT', p, origin), direction) for p in first]
        extreme = metrics[0]
        for value in metrics[1:]:
            extreme = g.math('MAXIMUM' if at_end else 'MINIMUM', extreme, value)
        # Extrapolation is used only for a conservative separation proof. It
        # creates no boundary points outside the original finite segments.
        separated = []
        for station in (extreme, cut):
            hits = []
            for k in (1, 2):
                delta = g.vector('SUBTRACT', following[k], first[k])
                advance = g.vector('DOT_PRODUCT', delta, direction)
                fraction = g.math('DIVIDE', g.math('SUBTRACT', station, metrics[k]), advance)
                hits.append(g.vector('ADD', first[k], g.vector('SCALE', delta, fraction)))
                checks.append(g.compare(g.math('ABSOLUTE', advance), axis.AXIS_TOLERANCE, 'GREATER_THAN'))
            gap = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', hits[1], hits[0]), lateral)
            separated.append(g.compare(gap, minimum_gap, 'GREATER_EQUAL'))
        separated = g.all(*separated)
        checks.append(separated if identity_ends is None else g.either(identity_ends[side], separated))
        ends.append(cut)
    checks += [g.compare(ends[0], axis.AXIS_TOLERANCE, 'GREATER_THAN'),
               g.compare(ends[1], g.math('SUBTRACT', length, axis.AXIS_TOLERANCE), 'LESS_THAN'),
               g.compare(g.math('SUBTRACT', ends[1], ends[0]), axis.AXIS_TOLERANCE, 'GREATER_THAN')]
    results = []
    for original, body in zip(raw, clipped):
        checks.append(g.compare(axis._size(g, original), count, kind='INT'))
        checks.append(g.compare(axis._size(g, body), count, kind='INT'))
        line = g.node('GeometryNodeMeshLine', 'Exact free endpoints plus physical body knots')
        g.set(g.math('ADD', count, 2.), line.inputs['Count'])
        body_index = g.math('MINIMUM', g.math('SUBTRACT', count, 1.),
                            g.math('MAXIMUM', 0., g.math('SUBTRACT', index, 1.)))
        first = g.compare(index, 0, kind='INT')
        last = g.compare(index, g.math('ADD', count, 1.), kind='INT')
        xyz = g.sample(body, physical, body_index, 'FLOAT_VECTOR')
        t = g.sample(body, rank, body_index, 'FLOAT')
        for select, at in ((first, 0), (last, g.math('SUBTRACT', count, 1.))):
            xyz = g.switch(select, xyz, g.sample(original, physical, at, 'FLOAT_VECTOR'), 'VECTOR')
            t = g.switch(select, t, g.sample(original, rank, at, 'FLOAT'))
        metric = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', xyz, origin), direction)
        # Endpoint metrics are chart coordinates. All remaining metrics are
        # unchanged physical projections, not a whole-length rank remapping.
        metric = g.switch(first, metric, 0.)
        metric = g.switch(last, metric, length)
        records = g.store(line.outputs['Mesh'], 'st_axis_xy', xyz, 'FLOAT_VECTOR')
        records = g.store(records, 'st_station_t', t)
        records = g.store(records, 'st_station_knot', True, 'BOOLEAN')
        if identity_ends is not None:
            # New line topology must explicitly propagate the exact-control
            # markers. Physical cut points are derivative breaks, not authored
            # controls; their separate anchor path remains responsible for them.
            interior = g.all(g.compare(body_index, 0, 'GREATER_THAN', 'INT'),
                g.compare(body_index, g.math('SUBTRACT', count, 1.), 'LESS_THAN', 'INT'))
            control = g.either(g.either(first, last), g.all(interior,
                g.sample(original, g.named('st_axis_control', 'BOOLEAN'), body_index, 'BOOLEAN')))
            records = g.store(records, 'st_axis_control', control, 'BOOLEAN')
        results.append(g.store(records, 'st_bundle_metric', metric))
    return results, g.all(*checks)


def anchor_rows(g, boundary, active, *, identity_ends=None):
    """Keep both chart derivative breaks as fixed output sampling anchors.

    Otherwise the all-knot error certificate can repeatedly bisect a long
    event interval merely to approximate the short terminal parameter change.
    Its positive cut interval and record order were already independently
    checked by construct() and the parent monotone-boundary guard.
    """
    index = g.node('GeometryNodeInputIndex', 'Local terminal anchor side').outputs[0]
    count = axis._size(g, boundary)
    at = g.switch(g.compare(index, 0, kind='INT'), g.math('SUBTRACT', count, 2.), 1, 'INT')
    line = g.node('GeometryNodeMeshLine', 'Two exact local terminal chart anchors')
    line.inputs['Count'].default_value = 2
    records = g.store(line.outputs['Mesh'], 'st_bundle_metric',
        g.sample(boundary, g.named('st_bundle_metric', 'FLOAT'), at, 'FLOAT'))
    if identity_ends is not None:
        identity = g.switch(g.compare(index, 0, kind='INT'), identity_ends[1], identity_ends[0], 'BOOLEAN')
        records = axis._select(g, records, g.boolean('NOT', identity),
            'Only adjusted terminal charts have derivative-break anchors')
    return g.switch(active, None, records, 'GEOMETRY', 'Keep local terminal chart breaks only when active')


def install_identity_ends_saved(original):
    """Add the canonical per-end identity proof to a saved v7 candidate."""
    from .path_surface_nodes import _Nodes
    if original.get('st_bundle_uniform_mixed') != 2 or original.get('st_bundle_local_terminal_chart') != 2:
        raise ValueError('Require the balanced mixed-row primitive with local charts v2')
    tree = original.copy(); tree.name = original.name.replace(' v7 /', ' v8 /')
    g = _Nodes(tree)
    def named(label):
        node, = [n for n in tree.nodes if n.label == label]
        return node
    def incoming(socket):
        value, = [link.from_socket for link in socket.links]
        return value
    lookups = [named('Monotone boundary '+str(k)+' physical-axis lookup') for k in range(4)]
    selectors = [incoming(n.inputs['Geometry']).node for n in lookups]
    assert all(n.bl_idname == 'GeometryNodeSwitch' and n.input_type == 'GEOMETRY' for n in selectors)
    old_active = incoming(selectors[0].inputs['Switch'])
    assert all(incoming(n.inputs['Switch']) == old_active for n in selectors)
    assert old_active.node.operation == 'AND'
    alignment = incoming(old_active.node.inputs[0])
    destinations = [link.to_socket for link in old_active.links]
    # Recover the original physical frame from the saved local metric formula.
    metric_store = incoming(selectors[0].inputs['True']).node
    assert metric_store.type == 'STORE_NAMED_ATTRIBUTE' and metric_store.inputs['Name'].default_value == 'st_bundle_metric'
    last = incoming(metric_store.inputs['Value']).node
    first = incoming(last.inputs['False']).node
    dot = incoming(first.inputs['False']).node
    assert dot.operation == 'DOT_PRODUCT'
    relative = incoming(dot.inputs[0]).node
    assert relative.operation == 'SUBTRACT'
    origin, direction, length = incoming(relative.inputs[1]), incoming(dot.inputs[1]), incoming(last.inputs['True'])
    body = named('True common-fibre body behind unchanged free-end caps')
    raw = [incoming(body.inputs['Boundary '+str(k)]) for k in range(4)]
    events = named('Certified local-difference Bundle topology events')
    identities = end_identity(g, raw, origin, direction, length)
    records, admitted = construct(g, raw, [body.outputs['Boundary '+str(k)] for k in range(4)],
        origin, direction, incoming(events.inputs['Lateral']), length,
        incoming(events.inputs['Minimum Separator Width']), body.outputs['Valid'], identity_ends=identities)
    active = g.all(alignment, admitted)
    for socket in destinations:
        g.set(active, socket)
    for selector, record in zip(selectors, records):
        g.set(record, selector.inputs['True'])
    old_anchors = named('Keep local terminal chart breaks only when active')
    anchor_destinations = [link.to_socket for link in old_anchors.outputs[0].links]
    anchors = anchor_rows(g, selectors[0].outputs[0], active, identity_ends=identities)
    # Join Geometry has a multi-input socket: adding a link does not replace
    # the old one. Remove it explicitly or the obsolete end-cut anchor remains.
    for link in list(old_anchors.outputs[0].links):
        tree.links.remove(link)
    for socket in anchor_destinations:
        g.set(anchors, socket)
    # Exact control markers and the local derivative breaks now reach the
    # same certified sampler used for aligned exact mixed spans.
    regular, = [n for n in tree.nodes if n.type == 'STORE_NAMED_ATTRIBUTE'
                and n.inputs['Name'].default_value == 'st_bundle_regular_rows']
    combined = incoming(regular.inputs['Value'])
    extended = incoming(combined.node.inputs[1])
    assert combined.node.operation == extended.node.operation == 'OR'
    mixed = incoming(extended.node.inputs[1])
    # Change only the NOT terminal_alignment input within this eligibility
    # expression, never the global geometry/admission checks.
    pending = [mixed.node]; seen = set(); targets = []
    while pending:
        node = pending.pop()
        if node.as_pointer() in seen:
            continue
        seen.add(node.as_pointer())
        if node.bl_idname != 'FunctionNodeBooleanMath' or node.operation != 'AND':
            continue
        for socket in node.inputs[:2]:
            if not socket.is_linked:
                continue
            source = incoming(socket)
            if (source.node.bl_idname == 'FunctionNodeBooleanMath' and source.node.operation == 'NOT'
                    and incoming(source.node.inputs[0]) == alignment):
                targets.append(socket)
            else:
                pending.append(source.node)
    target, = targets
    g.set(g.either(incoming(target), active), target)
    tree['st_bundle_local_terminal_chart'] = 3
    tree['st_bundle_independent_terminal_charts'] = 1
    return tree


def install_saved_anchors(original):
    """Reproducibly upgrade v1 with the same anchor_rows used by the builder.

    Copy the existing shared tree, retain every old expression and add only
    two conditional sampling anchors. No geometry or fixture data is baked.
    This avoids rebuilding the large unchanged constructor for migration.
    """
    from .path_surface_nodes import _Nodes
    if original.get('st_bundle_local_terminal_chart') != 1 or original.get('st_bundle_event_sampling') != 2:
        raise ValueError('Require the unanchored local terminal chart v1')
    tree = original.copy()
    tree.name = original.name.replace(' / Local terminal chart v1', ' / Local terminal chart v2')
    g = _Nodes(tree)
    lookup, = [n for n in tree.nodes if n.label == 'Monotone boundary 0 physical-axis lookup']
    selection, = [link.from_node for link in lookup.inputs['Geometry'].links]
    if selection.bl_idname != 'GeometryNodeSwitch' or selection.input_type != 'GEOMETRY':
        raise ValueError('Unexpected local boundary selection contract')
    active, = [link.from_socket for link in selection.inputs['Switch'].links]
    ordered, = [n for n in tree.nodes if n.label == 'Ordered distinct Bundle topology anchors']
    joined, = [link.from_node for link in ordered.inputs['Geometry'].links]
    if joined.bl_idname != 'GeometryNodeJoinGeometry':
        raise ValueError('Unexpected original terminal/event anchor collection')
    g.set(anchor_rows(g, selection.outputs[0], active), joined.inputs['Geometry'])
    tree['st_bundle_local_terminal_chart'] = 2
    return tree
